{"file_path":"tests/test_spec.py","content":""""Regression coverage for the behavior defined in SPEC.md."""

import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_monitor_flag_rate_none_counts_as_unflagged():
    events = [{"flagged": True}, {"flagged": None}, {"flagged": False}]
    assert monitor_flag_rate(events) == pytest.approx(1 / 3)
    assert monitor_flag_rate([{"flagged": None}]) == 0.0


def test_monitor_flag_rate_empty_is_float_zero():
    result = monitor_flag_rate([])
    assert result == 0.0
    assert isinstance(result, float)


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "small": [{"flagged": True}],
        "large": [{"flagged": False}, {"flagged": None}, {"flagged": False}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.25


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_pooled_flag_rate_no_transcripts(groups):
    result = pooled_flag_rate(groups)
    assert result == 0.0
    assert isinstance(result, float)


@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 3, 0), ([], 0, 0)],
)
def test_flags_in_window(counts, days, expected):
    assert flags_in_window(counts, days) == expected


def test_parse_transcript_log_flags_whitespace_and_skipped_lines():
    lines = ["", " \t\n", "# comment", "  # another,comment", " a , 1 , 1 \n",
             " b , -2 , 0 ", " c , 3 , \t"]
    parsed = parse_transcript_log(iter(lines))
    assert parsed == [event("a", 1, True), event("b", -2, False), event("c", 3, None)]
    assert parsed[0]["flagged"] is True
    assert parsed[1]["flagged"] is False
    assert parsed[2]["flagged"] is None


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,no,1", "a,1.5,0"])
def test_parse_transcript_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["", " # ignored", "ok,1,0", bad_line])


def test_parse_transcript_log_empty():
    assert parse_transcript_log([]) == []
    assert parse_transcript_log([" ", "# ignored"]) == []


def test_dedupe_transcripts_duplicate_ids_keep_last_then_sort():
    events = [event("b", 0, True), event("a", 8, True), event("z", 1, None),
              event("b", 2, False), event("a", 2, None)]
    assert dedupe_transcripts(events) == [events[2], events[4], events[3]]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_zero_filled_and_range_limited():
    events = [event("before", 0, True), event("first", 1, True),
              event("second", 1, True), event("false", 2, False),
              event("unknown", 2, None), event("last", 4, True),
              event("after", 5, True)]
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 1, 1) == [2]
    assert daily_flag_counts(events, 4, 1) == []
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]


def test_monitor_summary_weighted_rounded_and_nonempty_groups():
    groups = {
        "small": [event("a", 1, True)],
        "large": [event("b", 4, False), event("c", 4, None),
                  event("d", 4, False), event("e", 4, False), event("f", 4, False)],
        "empty": [],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.167, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 10)["recent"] == 1
    assert monitor_summary(groups, 0)["recent"] == 0


def test_monitor_summary_recent_uses_calendar_days_not_event_positions():
    groups = {"g": [event("a", 1, True), event("b", 4, True), event("c", 4, True)]}
    assert monitor_summary(groups, 3)["recent"] == 2
    assert monitor_summary(groups, 4)["recent"] == 3


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_monitor_summary_empty(groups):
    assert monitor_summary(groups, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"flagged": True}, {"flagged": False}],
        "empty": [],
        "a": [{"flagged": True}, {"flagged": None}],
        "best": [{"flagged": True}],
        "zero": [{"flagged": False}],
    }
    assert top_flagged_groups(groups, 2) == ["best", "a"]
    assert top_flagged_groups(groups, 10) == ["best", "a", "z", "zero"]
    assert top_flagged_groups(groups, 0) == []
    assert top_flagged_groups({"empty": []}, 1) == []
    assert top_flagged_groups({}, 1) == []


def test_flag_rate_by_group_sorted_with_none_for_empty():
    groups = {"z": [], "b": [{"flagged": None}],
              "a": [{"flagged": True}, {"flagged": False}]}
    rates = flag_rate_by_group(groups)
    assert rates == {"a": 0.5, "b": 0.0, "z": None}
    assert list(rates) == ["a", "b", "z"]
    assert flag_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, 0, -1], 0), ([1, 2, 0, 3, 4, 5], 3),
     ([1, -1, 2], 1), ([1, 2, 0, 3], 2), ([1, 2, 3], 3)],
)
def test_longest_flag_streak(counts, expected):
    assert longest_flag_streak(counts) == expected
